def ans(arr):
	new_arr = []
	i = 0
	while i < len(arr):
		if i == 0:
			new_arr.append(arr[i] & arr[i + 1])
		elif i == len(arr) - 1:
			new_arr.append(arr[i] & arr[i - 1])
		else:
			new_arr.append(max(arr[i] & arr[i - 1], arr[i] & arr[i + 1]))
		i += 1
	return new_arr
